def I_numeric(mu=5, x_range=(-10,10), npts=50000):
    x=np.linspace(*x_range,npts)
    theta=(2*np.pi/3)*(1+np.tanh(mu*x))/2
    return np.trapz(np.sin(theta)**2,x)
I_numeric()

